using System.Security.Cryptography;
using DiscForge.Core.Chd;
using Xunit;

namespace DiscForge.Core.Tests;

/// <summary>
/// CHD extraction, validated against a real chdman-produced cdzl CD image
/// (single AUDIO track, 1200 frames) embedded here so the test is self-contained.
/// The extractor decompresses the hunks, self-verifies against the SHA-1 the CHD
/// stores of its own contents, and must reproduce the track byte-for-byte — which
/// is what turns "implemented from the format" into "confirmed against a real file".
/// </summary>
public class ChdExtractorTests
{
    private static byte[] Sample() => System.Convert.FromBase64String(ChdBase64);

    [Fact]
    public void RealCdzlChd_ExtractsVerifiedAndByteExact()
    {
        var r = ChdExtractor.ExtractCd(Sample());
        Assert.True(r.Verified);
        Assert.Equal(1, r.Tracks);
        Assert.Equal(2822400, r.Bin.Length);
        string sha = System.Convert.ToHexString(SHA256.HashData(r.Bin)).ToLowerInvariant();
        Assert.Equal("ba42d5132f62d7f39fe8ce186f32e71de3c06653154905fc0123052abde59ebd", sha);
    }

    [Fact]
    public void Identify_reads_the_track_metadata()
    {
        var info = ChdReader.Read(Sample());
        Assert.Single(info.Tracks);
        Assert.Equal("AUDIO", info.Tracks[0].Type);
        Assert.Equal(1200, info.Tracks[0].Frames);
        Assert.Equal("cdzl", info.Compressors[0]);
    }

